using Agent.Core.Security;

namespace Agent.Tests;

public class SecureChannelTests
{
    private static readonly byte[] Secret = Enumerable.Range(0, 32).Select(i => (byte)i).ToArray();
    private static readonly byte[] Cn = Enumerable.Range(0, 16).Select(i => (byte)(0x10 + i)).ToArray();
    private static readonly byte[] Sn = Enumerable.Range(0, 16).Select(i => (byte)(0x20 + i)).ToArray();
    private static readonly byte[] Plain = { 1, 2, 3, 4, 5, 0xaa, 0xbb };

    // Generated by the Dart SecureChannel (client role encrypt / server role encrypt).
    private const string C2s0 = "00000000000000002ba9411e0be75ee32b4810199186eb6cd65d1a6260c396";
    private const string C2s1 = "0000000000000001bb0fd18d52419e6a030321007a298b789efe055237b9e3";
    private const string S2c0 = "00000000000000002d8ec789aeb1f77bd6fe968f1d982b95eeccdf5ce52e21";

    private static SecureChannel Server() => SecureChannel.Create(Secret, Cn, Sn, ChannelRole.Server);
    private static SecureChannel Client() => SecureChannel.Create(Secret, Cn, Sn, ChannelRole.Client);

    [Fact]
    public void DecryptsDartClientMessagesAndRejectsReplay()
    {
        var s = Server();
        Assert.Equal(Plain, s.Decrypt(Convert.FromHexString(C2s0)));
        Assert.Null(s.Decrypt(Convert.FromHexString(C2s0)));
        Assert.Equal(Plain, s.Decrypt(Convert.FromHexString(C2s1)));
    }

    [Fact]
    public void EncryptMatchesDartOutput()
    {
        Assert.Equal(S2c0, Convert.ToHexString(Server().Encrypt(Plain)).ToLowerInvariant());
        Assert.Equal(C2s0, Convert.ToHexString(Client().Encrypt(Plain)).ToLowerInvariant());
    }

    [Fact]
    public void TamperedOrShortMessagesReturnNullWithoutAdvancingState()
    {
        var s = Server();
        var bad = Convert.FromHexString(C2s0);
        bad[10] ^= 1;
        Assert.Null(s.Decrypt(bad));
        Assert.Null(s.Decrypt(new byte[23]));
        Assert.Equal(Plain, s.Decrypt(Convert.FromHexString(C2s0)));
    }

    [Fact]
    public void RoundTripBetweenClientAndServer()
    {
        var c = Client();
        var s = Server();
        Assert.Equal(Plain, s.Decrypt(c.Encrypt(Plain)));
        Assert.Equal(Array.Empty<byte>(), c.Decrypt(s.Encrypt(Array.Empty<byte>())));
    }
}
